terraform {
  required_version = ">= 1.10"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 4.6"
    }
  }
}

# Talks to Docker on your laptop. No cloud account needed.
provider "docker" {}

variable "app_image" {
  description = "The app image to run (build it first with docker build)."
  type        = string
  default     = "hello-devops:1.0.0"
}

variable "app_version" {
  description = "Shown by the app at /."
  type        = string
  default     = "1.0.0"
}

variable "host_port" {
  description = "Port on your laptop that forwards to the app."
  type        = number
  default     = 8080
}

# A private network so the app can reach Redis by name.
resource "docker_network" "app" {
  name = "hello-net"
}

resource "docker_image" "redis" {
  name = "redis:8-alpine"
}

resource "docker_container" "redis" {
  name  = "hello-redis"
  image = docker_image.redis.image_id
  networks_advanced {
    name = docker_network.app.name
  }
}

resource "docker_container" "web" {
  name  = "hello-web"
  image = var.app_image
  env = [
    "REDIS_HOST=${docker_container.redis.name}",
    "APP_VERSION=${var.app_version}",
  ]
  ports {
    internal = 8000
    external = var.host_port
  }
  networks_advanced {
    name = docker_network.app.name
  }
}

output "url" {
  description = "Open this in your browser."
  value       = "http://localhost:${var.host_port}"
}

