code.src:
terraform {
  required_version = ">= 1.11"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }

  # Step 2 (after the first apply): uncomment this block, put in your bucket
  # name from `terraform output bucket_name`, then run:
  #   terraform init -migrate-state
  # backend "s3" {
  #   bucket       = "hello-devops-tfstate-123456789012"
  #   key          = "infra/aws/terraform.tfstate"
  #   region       = "us-east-1"
  #   encrypt      = true
  #   use_lockfile = true # a small lock file in S3, no DynamoDB table needed
  # }
}

provider "aws" {
  region = var.region

  # Every resource this provider creates gets these tags.
  default_tags {
    tags = {
      Project   = var.project
      ManagedBy = "terraform"
      Repo      = "${var.github_owner}/${var.github_repo}"
    }
  }
}

variable "region" {
  description = "AWS Region for everything in this folder."
  type        = string
  default     = "us-east-1"
}

variable "project" {
  description = "Short name used in resource names and tags."
  type        = string
  default     = "hello-devops"
}

variable "github_owner" {
  description = "Your GitHub user name, for example octocat."
  type        = string
}

variable "github_repo" {
  description = "Your repository name."
  type        = string
  default     = "hello-devops"
}

variable "github_owner_id" {
  description = "Numeric ID of your GitHub user: gh api users/YOUR_USER --jq .id"
  type        = string
}

variable "github_repo_id" {
  description = "Numeric ID of your repo: gh api repos/YOUR_USER/hello-devops --jq .id"
  type        = string
}

# Who am I? Gives us the 12-digit account ID for a unique bucket name.
data "aws_caller_identity" "current" {}

# A private bucket. Later it also holds this folder's Terraform state.
# trivy:ignore:AWS-0089 Access logs need a second bucket. Not worth it for a lab.
resource "aws_s3_bucket" "state" {
  bucket = "${var.project}-tfstate-${data.aws_caller_identity.current.account_id}"

  # Lab only: lets `terraform destroy` delete the bucket even if it holds
  # files. For a real state bucket, remove this and add prevent_destroy.
  force_destroy = true
}

# Keep every old version of every file, so a bad state write can be undone.
resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Nobody on the internet can read this bucket, even by mistake.
resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Encrypt files at rest with keys that S3 manages (free).
# trivy:ignore:AWS-0132 A customer managed KMS key costs money each month.
resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Lets GitHub Actions log in to AWS with short-lived tokens (OIDC).
# No AWS keys are stored in GitHub. An account can have only one of these.
resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

locals {
  # GitHub puts the repo in the token's "sub" claim in one of two forms.
  # Repos created after July 15, 2026 use the second one, with numeric IDs.
  sub_by_name = "repo:${var.github_owner}/${var.github_repo}"
  sub_by_id   = "repo:${var.github_owner}@${var.github_owner_id}/${var.github_repo}@${var.github_repo_id}"
}

# Who may use the role: only your repo, and only for pull requests
# (plan) or jobs that run in the "production" environment (apply).
data "aws_iam_policy_document" "trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values = [
        "${local.sub_by_name}:pull_request",
        "${local.sub_by_id}:pull_request",
        "${local.sub_by_name}:environment:production",
        "${local.sub_by_id}:environment:production",
      ]
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name               = "${var.project}-github-actions"
  assume_role_policy = data.aws_iam_policy_document.trust.json
}

# What the role may do: manage this project's S3 buckets (including the
# state bucket), and read its own IAM setup so `terraform plan` works.
# Changes to IAM itself are applied from your laptop, never from CI.
# trivy:ignore:AWS-0345 s3:* is limited to this project's buckets.
data "aws_iam_policy_document" "permissions" {
  statement {
    sid     = "ProjectBuckets"
    actions = ["s3:*"]
    resources = [
      "arn:aws:s3:::${var.project}-*",
      "arn:aws:s3:::${var.project}-*/*",
    ]
  }
  statement {
    sid     = "ReadOwnIam"
    actions = ["iam:Get*", "iam:List*"]
    resources = [
      aws_iam_openid_connect_provider.github.arn,
      aws_iam_role.github_actions.arn,
    ]
  }
}

resource "aws_iam_role_policy" "github_actions" {
  name   = "terraform"
  role   = aws_iam_role.github_actions.id
  policy = data.aws_iam_policy_document.permissions.json
}

output "bucket_name" {
  description = "Put this name in the backend block in versions.tf."
  value       = aws_s3_bucket.state.bucket
}

output "github_actions_role_arn" {
  description = "Save as the repository variable AWS_ROLE_ARN in GitHub."
  value       = aws_iam_role.github_actions.arn
}
